import unittest
from candidate import triples_sum_to_zero

class TestTriplesSumToZero(unittest.TestCase):
    def test_triples_sum_to_zero_normal_true(self):
        self.assertTrue(triples_sum_to_zero([1, 3, -2, 1]))
        self.assertTrue(triples_sum_to_zero([2, 4, -5, 3, 9, 7]))
        self.assertTrue(triples_sum_to_zero([0, -1, 1, -2, 2]))

    def test_triples_sum_to_zero_normal_false(self):
        self.assertFalse(triples_sum_to_zero([1, 3, 5, 0]))
        self.assertFalse(triples_sum_to_zero([1, 2, 3, 7]))
        self.assertFalse(triples_sum_to_zero([5, 1, 1]))

    def test_triples_sum_to_zero_fewer_than_three(self):
        self.assertFalse(triples_sum_to_zero([]))
        self.assertFalse(triples_sum_to_zero([1]))
        self.assertFalse(triples_sum_to_zero([1, 2]))

    def test_triples_sum_to_zero_duplicates_values(self):
        self.assertTrue(triples_sum_to_zero([1, 1, -2]))
        self.assertTrue(triples_sum_to_zero([-3, -3, 6]))

    def test_triples_sum_to_zero_empty_input(self):
        self.assertFalse(triples_sum_to_zero([]))

    def test_triples_sum_to_zero_none_input(self):
        with self.assertRaises(TypeError):
            triples_sum_to_zero(None)

    def test_triples_sum_to_zero_non_list_iterable_tuple(self):
        self.assertTrue(triples_sum_to_zero((1, -1, 0)))
        self.assertFalse(triples_sum_to_zero((1, 2, 3)))

    def test_triples_sum_to_zero_generator_input(self):
        gen = (x for x in [1, -1, 0])
        with self.assertRaises(TypeError):
            triples_sum_to_zero(gen)

    def test_triples_sum_to_zero_non_int_elements(self):
        self.assertFalse(triples_sum_to_zero(['1', '-1', '0']))
        self.assertFalse(triples_sum_to_zero(['a', 'b', 'c']))

    def test_triples_sum_to_zero_float_elements(self):
        self.assertTrue(triples_sum_to_zero([1.0, -1.0, 0.0]))
        self.assertTrue(triples_sum_to_zero([2, -2, 0.0]))
        self.assertFalse(triples_sum_to_zero([1.5, -1.5, 0.1]))

    def test_triples_sum_to_zero_none_inside(self):
        with self.assertRaises(TypeError):
            triples_sum_to_zero([1, None, -1])

    def test_triples_sum_to_zero_type_error_on_invalid_element(self):
        with self.assertRaises(TypeError):
            triples_sum_to_zero([1, 'a', -1])

    def test_triples_sum_to_zero_original_list_unchanged(self):
        data = [1, 2, -3, 4, -4]
        original = data[:]
        triples_sum_to_zero(data)
        self.assertEqual(data, original)

if __name__ == "__main__":
    unittest.main()
